import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"31、【鹹】 艮下兌上","description":"橫渠易說 - 31、【鹹】 艮下兌上","frontmatter":{"title":"31、【鹹】 艮下兌上","description":"橫渠易說 - 31、【鹹】 艮下兌上"},"headers":[],"relativePath":"classics/hengqu/033.md","filePath":"classics/hengqu/033.md"}'),l={name:"classics/hengqu/033.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_31、【鹹】-艮下兌上" tabindex="-1">31、【鹹】 艮下兌上 <a class="header-anchor" href="#_31、【鹹】-艮下兌上" aria-label="Permalink to “31、【鹹】 艮下兌上”">​</a></h1><p>鹹之為道，以虛受為本，有意於中，則滯於方體而隘矣。拇、腓、股、脢、輔，以一卦通體高下為言。</p><h3 id="彖曰-鹹-感也-柔上而剛下-二氣感應以相與-止而說-男下女-是以-亨利貞取女吉-也。天地感而萬物化生-聖人感人心而天下和平-觀其所感而天地萬物之情可見矣。" tabindex="-1">彖曰：鹹，感也，柔上而剛下，二氣感應以相與，止而說，男下女，是以“亨利貞取女吉”也。天地感而萬物化生，聖人感人心而天下和平，觀其所感而天地萬物之情可見矣。 <a class="header-anchor" href="#彖曰-鹹-感也-柔上而剛下-二氣感應以相與-止而說-男下女-是以-亨利貞取女吉-也。天地感而萬物化生-聖人感人心而天下和平-觀其所感而天地萬物之情可見矣。" aria-label="Permalink to “彖曰：鹹，感也，柔上而剛下，二氣感應以相與，止而說，男下女，是以“亨利貞取女吉”也。天地感而萬物化生，聖人感人心而天下和平，觀其所感而天地萬物之情可見矣。”">​</a></h3><p>鹹，感也，其爻雖相應而詞多不吉，顧其時如何耳。說者多以鹹恆配天地，殊不知鹹自可配天 地，故於序卦獨不言鹹。鹹既可以配天地，則恆亦可以配天地，皆夫婦之道也。鹹之為言皆也，故語 鹹則非事。“鹹感也”，不可止以夫婦之道謂之鹹，此一事耳，男女相配，故為鹹也。感之道不一：或 以同而感，聖人感人心以道，此是以同也；或以異而應，男女是也，二女同居則無感也；或以相悅而 感，或以相畏而感，如虎先見犬，犬自不能去，犬若見虎則能避之；又如磁石引針，相應而感也。若以 愛心而來者自相親，以害心而來者相見容色自別。“聖人感人心而天下和平”，是風動之也；聖人老 吾老以及人之老而人慾老其老，此是以事相感也。感如影響，無復先後，有動必感，鹹感而應，故曰 鹹速也。</p><h3 id="象曰-山上有澤-鹹-君子以虛受人。" tabindex="-1">象曰：山上有澤，鹹，君子以虛受人。 <a class="header-anchor" href="#象曰-山上有澤-鹹-君子以虛受人。" aria-label="Permalink to “象曰：山上有澤，鹹，君子以虛受人。”">​</a></h3><p>山上有澤，非交感不能也。感物之善，莫若以虛受人，有所繫慕，皆非正吉，故六爻皆以有應不盡卦義而有所譏也。</p><h3 id="初六-鹹其拇。-象曰-鹹其拇-志在外也。" tabindex="-1">初六，鹹其拇。 象曰：“鹹其拇”，志在外也。 <a class="header-anchor" href="#初六-鹹其拇。-象曰-鹹其拇-志在外也。" aria-label="Permalink to “初六，鹹其拇。 象曰：“鹹其拇”，志在外也。”">​</a></h3><h3 id="六二-鹹其腓-兇-居吉。-象曰-雖兇居吉-順不害也。" tabindex="-1">六二，鹹其腓，兇，居吉。 象曰：雖兇居吉，順不害也。 <a class="header-anchor" href="#六二-鹹其腓-兇-居吉。-象曰-雖兇居吉-順不害也。" aria-label="Permalink to “六二，鹹其腓，兇，居吉。 象曰：雖兇居吉，順不害也。”">​</a></h3><p>居則吉，趨則兇，以男下女為正，鹹之道也。</p><h3 id="九三-鹹其股-執其隨-往吝。-象曰-鹹其股-亦不處也-志在隨人-所執下也。" tabindex="-1">九三，鹹其股，執其隨，往吝。 象曰：“鹹其股”，亦不處也；志在隨人，所執下也。 <a class="header-anchor" href="#九三-鹹其股-執其隨-往吝。-象曰-鹹其股-亦不處也-志在隨人-所執下也。" aria-label="Permalink to “九三，鹹其股，執其隨，往吝。 象曰：“鹹其股”，亦不處也；志在隨人，所執下也。”">​</a></h3><p>心寧靜於此，一向定疊，前縱有何事亦不恤也，休將閒細碎在思慮。易曰：“何思何慮？天下殊 塗而同歸，一致而百慮。”天地之道，惟有日月、寒暑之往來，屈伸、動靜兩端而已，在我精義入神以致 用，則細碎皆不能出其間，在於術內，已過、未來者事著在心，畢竟何益!浮思遊想盡去之，惟圖向去 日新可也。孔子以富不可求，則曰“從吾所好”，以思為無益，則曰“不如學也”，故於鹹三以見此義。</p><h3 id="九四-貞吉-悔亡。憧憧往來-朋從爾思。-象曰-貞吉悔亡-未感害也。-憧憧往來-未光大也。" tabindex="-1">九四，貞吉，悔亡。憧憧往來，朋從爾思。 象曰：“貞吉悔亡”，未感害也。“憧憧往來”，未光大也。 <a class="header-anchor" href="#九四-貞吉-悔亡。憧憧往來-朋從爾思。-象曰-貞吉悔亡-未感害也。-憧憧往來-未光大也。" aria-label="Permalink to “九四，貞吉，悔亡。憧憧往來，朋從爾思。 象曰：“貞吉悔亡”，未感害也。“憧憧往來”，未光大也。”">​</a></h3><p>釋氏以感為幻妄，又有憧憧思以求朋者，皆不足道也。 以陽居陰，非躁感於物者也，然體兌性悅，未免乎思以求朋之累也。蓋體悅之初，應止之始，己勞於上，朋止於下，故憧憧得朋，未為光大，不持以正則有謅瀆之悔。 感非有意，鹹三思以求朋，此則不足道。 聖人惟於屈伸有感，能有屈伸，所以得天下之物，何用憧憧以思而求朋!大抵鹹卦六爻皆以有應不盡鹹道，故君子欲得虛受人，能容以虛，受人之道也。苟曉屈伸，心盡安泰寬裕，蓋為不與物校，待彼伸則己屈，然而屈時少，伸時多，假使亂［亡］橫逆，亦猶屈少伸多，我尚何傷!日月寒暑往來，正以相屈伸故不相害。尺蠖之屈以求伸，龍蛇之蟄以存身，又精義入神以致用，利用安身以崇德。</p><h3 id="九五-鹹其脢-無悔。-象曰-鹹其脢-志末也。" tabindex="-1">九五，鹹其脢，無悔。 象曰：“鹹其脢”，志末也。 <a class="header-anchor" href="#九五-鹹其脢-無悔。-象曰-鹹其脢-志末也。" aria-label="Permalink to “九五，鹹其脢，無悔。 象曰：“鹹其脢”，志末也。”">​</a></h3><p>九五處悅之中，未免偏系之弊，故不能感人心，而曰“鹹其脢”，惟聖人然後能感人心也。一無曰字。</p><h3 id="上六-鹹其輔、頰、舌。-象曰-鹹其輔、頰、舌-滕口說也。" tabindex="-1">上六，鹹其輔、頰、舌。 象曰：“鹹其輔、頰、舌”，滕口說也。 <a class="header-anchor" href="#上六-鹹其輔、頰、舌。-象曰-鹹其輔、頰、舌-滕口說也。" aria-label="Permalink to “上六，鹹其輔、頰、舌。 象曰：“鹹其輔、頰、舌”，滕口說也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
